# Command generation --------------------------------------------------------
#
# Pure functions that reproduce the R code generated by the corresponding
# Rcmdr dialogs.  Keeping them free of Shiny makes them directly testable and
# documents the contract of each dialog.

#' Command generated by the "Read Text Data" dialog
#'
#' Mirrors `readDataSet()` in Rcmdr's `data-menu.R`.
#' @keywords internal
read_text_command <- function(dsname, header = TRUE, stringsAsFactors = TRUE,
                              delimiter = "whitespace", other = "",
                              missing = "NA", decimal = "period",
                              location = "local", path = "", url = "") {
  file <- switch(
    location,
    local = quote_string(path),
    url = quote_string(url),
    clipboard = if (identical(Sys.info()[["sysname"]], "Darwin")) {
      'pipe("pbpaste")'
    } else {
      quote_string("clipboard")
    },
    stop("Unknown data source.", call. = FALSE)
  )

  sep <- switch(
    delimiter,
    whitespace = "",
    commas = ",",
    semicolons = ";",
    tabs = "\\t",
    other = other,
    stop("Unknown field separator.", call. = FALSE)
  )
  dec <- if (identical(decimal, "period")) "." else ","

  command <- paste0(
    "read.table(", file,
    ", header=", isTRUE(header),
    ", stringsAsFactors=", isTRUE(stringsAsFactors),
    ', sep="', sep,
    '", na.strings="', missing,
    '", dec="', dec,
    '", strip.white=TRUE)'
  )
  paste0(dsname, " <- ", command)
}

#' Commands generated by the "Numerical Summaries" dialog
#'
#' Mirrors `numericalSummaries()` in Rcmdr's `statistics-summaries-menu.R`.
#'
#' @param dataset Name of the active data set.
#' @param x Variables to summarise.
#' @param discrete Subset of `x` that Rcmdr treats as discrete numeric.
#' @param groups Optional grouping variable (a factor).
#' @param group_levels Levels of `groups`, needed by frequency-count commands.
#' @param quantiles_values Text entered in the quantiles field.
#' @keywords internal
num_summary_commands <- function(dataset, x,
                                 mean = TRUE, sd = TRUE, se.mean = FALSE,
                                 var = FALSE, IQR = TRUE, cv = FALSE,
                                 counts = FALSE, quantiles = TRUE,
                                 quantiles_values = "0, .25, .5, .75, 1",
                                 skewness = FALSE, kurtosis = FALSE,
                                 type = "2", groups = NULL,
                                 group_levels = NULL,
                                 discrete = character()) {
  if (length(x) == 0L) return(character())

  ds_vars <- paste0(dataset, "[,", quote_vars(x), ", drop=FALSE]")

  flags <- c(
    mean = isTRUE(mean), sd = isTRUE(sd), se.mean = isTRUE(se.mean),
    var = isTRUE(var), IQR = isTRUE(IQR), quantiles = isTRUE(quantiles),
    cv = isTRUE(cv), skewness = isTRUE(skewness), kurtosis = isTRUE(kurtosis)
  )
  labels <- c(
    mean = '"mean"', sd = '"sd"', se.mean = '"se(mean)"',
    var = '"var"', IQR = '"IQR"', quantiles = '"quantiles"',
    cv = '"cv"', skewness = '"skewness"', kurtosis = '"kurtosis"'
  )
  statistics <- paste0("c(", paste(labels[flags], collapse = ", "), ")")

  qarg <- quantiles_argument(quantiles_values)
  type.text <- if (isTRUE(skewness) || isTRUE(kurtosis)) {
    paste0(', type="', type, '"')
  } else {
    ""
  }

  commands <- character()

  if (!identical(statistics, "c()")) {
    command <- if (!is.null(groups)) {
      paste0(
        "numSummary(", ds_vars, ", groups=", dataset, "$", groups,
        ", statistics=", statistics, ", quantiles=", qarg, type.text, ")"
      )
    } else {
      paste0(
        "numSummary(", ds_vars, ", statistics=", statistics,
        ", quantiles=", qarg, type.text, ")"
      )
    }
    commands <- c(commands, command)
  }

  if (isTRUE(counts)) {
    discrete <- intersect(discrete, x)
    continuous <- setdiff(x, discrete)

    if (is.null(groups)) {
      if (length(continuous) > 0L) {
        commands <- c(commands, paste0(
          "binnedCounts(", dataset, "[,", quote_vars(continuous), ", drop=FALSE])"
        ))
      }
      if (length(discrete) > 0L) {
        commands <- c(commands, paste0(
          "discreteCounts(", dataset, "[,", quote_vars(discrete), ", drop=FALSE])"
        ))
      }
    } else {
      levels <- group_levels %||% character()
      for (level in levels) {
        if (length(continuous) > 0L) {
          commands <- c(commands, paste0(
            "binnedCounts(", dataset, "[", dataset, "$", groups, " == '", level,
            "', ", quote_vars(continuous), ", drop=FALSE])\n  # ", groups, " = ", level
          ))
        }
        if (length(discrete) > 0L) {
          commands <- c(commands, paste0(
            "discreteCounts(", dataset, "[", dataset, "$", groups, " == '", level,
            "', ", quote_vars(discrete), ", drop=FALSE])\n  # ", groups, " = ", level
          ))
        }
      }
    }
  }

  commands
}

# Rcmdr normalises the free-text quantiles field by replacing spaces with
# commas and collapsing repeated commas.
quantiles_argument <- function(values) {
  if (is.null(values) || !nzchar(trimws(values))) return("c()")
  values <- gsub(",+", ",", gsub(" ", ",", values))
  values <- sub("^,", "", values)
  values <- sub(",$", "", values)
  paste0("c(", values, ")")
}

#' Commands generated by the "Linear Model" dialog
#'
#' Mirrors `linearModel()` in Rcmdr's `statistics-models-menu.R`.
#' @keywords internal
lm_commands <- function(dataset, model_name, lhs, rhs,
                        subset = "", weights = "", remove_rows = "") {
  args <- ""
  if (nzchar(subset)) args <- paste0(args, ", subset=", subset)
  if (nzchar(weights)) args <- paste0(args, ", weights=", weights)
  if (nzchar(remove_rows)) args <- paste0(args, ", subset =", remove_rows)

  command <- paste0(
    "lm(", lhs, " ~ ", rhs, ", data=", dataset, args, ")"
  )
  c(paste0(model_name, " <- ", command), paste0("summary(", model_name, ")"))
}

# Translate the "rows to remove" field into an R subset expression, following
# Rcmdr's getCases().  Returns a list with either `value` or `error`.
cases_subset <- function(dataset, df, cases) {
  tokens <- scan(text = gsub(",", " ", cases), what = "", quiet = TRUE)
  if (length(tokens) == 0L) return(list(value = ""))

  numbers <- suppressWarnings(as.numeric(tokens))
  if (!anyNA(numbers)) {
    bad <- numbers[!numbers %in% seq_len(nrow(df))]
    if (length(bad) > 0L) {
      return(list(error = paste(
        tr("bad row numbers:"), paste(bad, collapse = ", ")
      )))
    }
    return(list(value = paste0("-c(", paste(numbers, collapse = ", "), ")")))
  }

  bad <- tokens[!tokens %in% rownames(df)]
  if (length(bad) > 0L) {
    return(list(error = paste(
      tr("bad row names:"), paste(bad, collapse = ", ")
    )))
  }
  value <- paste0(
    "!(rownames(", dataset, ") %in% c(",
    paste0("'", tokens, "'", collapse = ", "), "))"
  )
  list(value = value)
}
